import React, { useState, useEffect } from 'react';

interface AgentStatus {
  name: string;
  role: string;
  status: 'optimal' | 'auditing' | 'deploying' | 'idle';
}

const FLEET_ROSTER: AgentStatus[] = [
  { name: 'Michael Scott', role: 'Floor Orchestrator', status: 'optimal' },
  { name: 'Dwight Schrute', role: 'Security Auditor', status: 'auditing' },
  { name: 'Jim Halpert', role: 'Marketing & Outreach', status: 'optimal' },
  { name: 'Pam Beesly', role: 'HR & People Ops', status: 'optimal' },
  { name: 'Kevin Malone', role: 'Finance & Accounting', status: 'optimal' },
  { name: 'Ryan Howard', role: 'Growth Strategist', status: 'optimal' },
  { name: 'Stanley Hudson', role: 'OSINT & Architecture', status: 'optimal' },
  { name: 'Toby Flenderson', role: 'DevOps / Auto-Debugger', status: 'optimal' },
  { name: 'Ruflo & Cline', role: 'Autonomous Coders', status: 'deploying' },
];

export const FleetStandupDashboard: React.FC = () => {
  const [currentTime, setCurrentTime] = useState(new Date().toLocaleTimeString());

  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date().toLocaleTimeString()), 1000);
    return () => clearInterval(timer);
  }, []);

  return (
    <div className="p-6 bg-slate-900 text-white rounded-xl shadow-2xl border border-slate-700 font-sans">
      <div className="flex justify-between items-center mb-4 border-b border-slate-700 pb-3">
        <div>
          <h2 className="text-xl font-bold text-amber-400">Dunder Mifflin Fleet Standup</h2>
          <p className="text-sm text-slate-400">All-Hands Hourly Sync • User: Michael G. Scott</p>
        </div>
        <div className="text-right">
          <span className="text-xs bg-emerald-500/20 text-emerald-300 px-3 py-1 rounded-full border border-emerald-500/30 font-mono">
            SYNC TIME: {currentTime}
          </span>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
        {FLEET_ROSTER.map((agent, index) => (
          <div key={index} className="bg-slate-800/80 p-3 rounded-lg border border-slate-700/60 flex items-center justify-between">
            <div>
              <p className="font-semibold text-sm text-slate-100">{agent.name}</p>
              <p className="text-xs text-slate-400">{agent.role}</p>
            </div>
            <div className="flex items-center space-x-2">
              <span className={`w-2.5 h-2.5 rounded-full ${
                agent.status === 'optimal' ? 'bg-emerald-400 animate-pulse' :
                agent.status === 'auditing' ? 'bg-amber-400' :
                agent.status === 'deploying' ? 'bg-cyan-400 animate-bounce' : 'bg-slate-500'
              }`} />
              <span className="text-xs capitalize text-slate-300 font-mono">{agent.status}</span>
            </div>
          </div>
        ))}
      </div>

      <div className="mt-4 pt-3 border-t border-slate-700 text-center text-xs text-slate-400 italic">
        "An autonomous fleet is only as strong as its most enthusiastic regional manager." — Pam Beesly
      </div>
    </div>
  );
};

export default FleetStandupDashboard;

// AI Mirchi Feature Module - Munderdiffl.in Fleet Operations
import React, { useState } from 'react';

interface MirchiTaskProps {
  taskName: string;
  spiceLevel: 'Mild' | 'Medium' | 'Hot' | 'Ghost Pepper (Critical)';
  assignedAgent: string;
}

export const AIMirchiDashboard: React.FC = () => {
  const [tasks, setTasks] = useState<MirchiTaskProps[]>([
    { taskName: 'LLM Prompt Tuning for Paper Recommendations', spiceLevel: 'Hot', assignedAgent: 'Cline Coder' },
    { taskName: 'Perimeter Defense Audit against Prompt Injection', spiceLevel: 'Ghost Pepper (Critical)', assignedAgent: 'Dwight Schrute' },
    { taskName: 'Viral TikTok Funnel Deployment', spiceLevel: 'Medium', assignedAgent: 'Ryan Howard' },
  ]);

  const [activeTab, setActiveTab] = useState<'overview' | 'deploy'>('overview');

  return (
    <div style={{ padding: '24px', background: '#111827', color: '#F9FAFB', borderRadius: '12px', fontFamily: 'sans-serif' }}>
      <header style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderBottom: '1px solid #374151', paddingBottom: '16px', marginBottom: '20px' }}>
        <div>
          <h1 style={{ margin: 0, fontSize: '24px', color: '#EF4444' }}>🌶️ Project: AI Mirchi Fleet Command</h1>
          <p style={{ margin: '4px 0 0 0', color: '#9CA3AF', fontSize: '14px' }}>Managed by Michael G. Scott & The Dunder Mifflin Autonomous Fleet</p>
        </div>
        <div style={{ display: 'flex', gap: '10px' }}>
          <button 
            onClick={() => setActiveTab('overview')}
            style={{ background: activeTab === 'overview' ? '#EF4444' : '#374151', color: '#fff', border: 'none', padding: '8px 16px', borderRadius: '6px', cursor: 'pointer' }}
          >
            Mission Status
          </button>
          <button 
            onClick={() => setActiveTab('deploy')}
            style={{ background: activeTab === 'deploy' ? '#EF4444' : '#374151', color: '#fff', border: 'none', padding: '8px 16px', borderRadius: '6px', cursor: 'pointer' }}
          >
            Deploy Spice Protocol
          </button>
        </div>
      </header>

      {activeTab === 'overview' ? (
        <div>
          <h3 style={{ color: '#F3F4F6' }}>Active Task Force Roster</h3>
          <table style={{ width: '100%', borderCollapse: 'collapse', marginTop: '12px' }}>
            <thead>
              <tr style={{ background: '#1F2937', textAlign: 'left', color: '#9CA3AF', fontSize: '12px', textTransform: 'uppercase' }}>
                <th style={{ padding: '12px' }}>Task Description</th>
                <th style={{ padding: '12px' }}>Spice Rating</th>
                <th style={{ padding: '12px' }}>Lead Agent</th>
              </tr>
            </thead>
            <tbody>
              {tasks.map((t, idx) => (
                <tr key={idx} style={{ borderBottom: '1px solid #374151' }}>
                  <td style={{ padding: '12px', fontWeight: '500' }}>{t.taskName}</td>
                  <td style={{ padding: '12px', color: t.spiceLevel.includes('Ghost') ? '#EF4444' : '#F59E0B' }}>{t.spiceLevel}</td>
                  <td style={{ padding: '12px', color: '#60A5FA' }}>{t.assignedAgent}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      ) : (
        <div style={{ background: '#1F2937', padding: '20px', borderRadius: '8px' }}>
          <h3 style={{ marginTop: 0, color: '#F3F4F6' }}>🚀 Emergency Fleet Deployment</h3>
          <p style={{ color: '#9CA3AF', fontSize: '14px' }}>All systems are calibrated. Click below to execute the full AI Mirchi pipeline across all 9 autonomous nodes.</p>
          <button 
            onClick={() => alert('🌶️ AI Mirchi pipeline successfully deployed across all fleet nodes! Dwights security seals are holding!')}
            style={{ background: '#EF4444', color: 'white', border: 'none', padding: '12px 24px', fontWeight: 'bold', borderRadius: '6px', cursor: 'pointer', marginTop: '10px' }}
          >
            Execute AI Mirchi Deployment NOW
          </button>
        </div>
      )}
    </div>
  );
};

export default AIMirchiDashboard;

