### 📄 The Invoice Generator Component (`ShopInvoice.tsx`)

Here is the code, ready to be mounted straight into our fleet architecture. It handles itemized billing, tax calculation, dynamic quantities, and a slick print-to-PDF/paper trigger.

```tsx
import React, { useState } from 'react';

interface InvoiceItem {
  id: string;
  description: string;
  quantity: number;
  unitPrice: number;
}

export const ShopInvoice: React.FC = () => {
  const [clientName, setClientName] = useState('Blue Cross / Blue Shield');
  const [clientEmail, setClientEmail] = useState('accounting@dundermifflin-competitor.com');
  const [items, setItems] = useState<InvoiceItem[]>([
    { id: '1', description: '20-lb Letter Paper (Ream)', quantity: 50, unitPrice: 8.50 },
    { id: '2', description: 'Colored Cardstock (Assorted)', quantity: 10, unitPrice: 14.99 },
  ]);
  const [taxRate, setTaxRate] = useState<number>(0.06); // Standard Pennsylvania sales tax

  const addItem = () => {
    setItems([
      ...items,
      { id: Date.now().toString(), description: 'New Paper Product', quantity: 1, unitPrice: 10.00 }
    ]);
  };

  const updateItem = (id: string, field: keyof InvoiceItem, value: string | number) => {
    setItems(items.map(item => item.id === id ? { ...item, [field]: value } : item));
  };

  const removeItem = (id: string) => {
    setItems(items.filter(item => item.id !== id));
  };

  const subtotal = items.reduce((acc, item) => acc + (item.quantity * item.unitPrice), 0);
  const taxAmount = subtotal * taxRate;
  const total = subtotal + taxAmount;

  const handlePrint = () => {
    window.print();
  };

  return (
    <div className="max-w-4xl mx-auto p-8 bg-white shadow-xl rounded-lg my-8 border border-gray-200 font-sans text-gray-800">
      {/* Header */}
      <div className="flex justify-between items-start border-b pb-6 mb-6">
        <div>
          <h1 className="text-3xl font-black tracking-wider text-red-700">DUNDER MIFFLIN</h1>
          <p className="text-sm text-gray-500">Paper Company - Scranton Branch</p>
          <p className="text-xs text-gray-400 mt-1">1725 Slough Avenue, Scranton, PA</p>
        </div>
        <div className="text-right">
          <h2 className="text-2xl font-bold text-gray-700">INVOICE</h2>
          <p className="text-sm text-gray-500 font-mono">INV-{Math.floor(100000 + Math.random() * 900000)}</p>
          <p className="text-xs text-gray-400 mt-1">Date: {new Date().toLocaleDateString()}</p>
        </div>
      </div>

      {/* Client Info Section */}
      <div className="grid grid-cols-2 gap-4 mb-8 bg-gray-50 p-4 rounded-md">
        <div>
          <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Billed To:</label>
          <input 
            type="text" 
            value={clientName} 
            onChange={(e) => setClientName(e.target.value)}
            className="w-full bg-white border border-gray-300 rounded px-2 py-1 text-sm font-medium"
          />
          <input 
            type="text" 
            value={clientEmail} 
            onChange={(e) => setClientEmail(e.target.value)}
            className="w-full bg-white border border-gray-300 rounded px-2 py-1 text-sm text-gray-500 mt-1"
          />
        </div>
        <div className="text-right flex flex-col justify-center">
          <span className="text-xs text-gray-400">Payment Terms: Net 30</span>
          <span className="text-xs text-red-600 font-semibold mt-1">⚠️ Late fees apply if Stanley doesn't get his pretzel break.</span>
        </div>
      </div>

      {/* Itemized Table */}
      <table className="w-full mb-6">
        <thead>
          <tr className="border-b-2 border-gray-300 text-left text-xs font-bold text-gray-600 uppercase">
            <th className="pb-2">Description</th>
            <th className="pb-2 text-center w-24">Qty</th>
            <th className="pb-2 text-right w-32">Unit Price</th>
            <th className="pb-2 text-right w-32">Amount</th>
            <th className="pb-2 text-center w-12"></th>
          </tr>
        </thead>
        <tbody className="divide-y divide-gray-200 text-sm">
          {items.map((item) => (
            <tr key={item.id}>
              <td className="py-3">
                <input 
                  type="text" 
                  value={item.description}
                  onChange={(e) => updateItem(item.id, 'description', e.target.value)}
                  className="w-full border-b border-transparent hover:border-gray-300 focus:border-red-500 focus:outline-none py-1"
                />
              </td>
              <td className="py-3 text-center">
                <input 
                  type="number" 
                  min="1"
                  value={item.quantity}
                  onChange={(e) => updateItem(item.id, 'quantity', parseInt(e.target.value) || 0)}
                  className="w-16 text-center border rounded py-1"
                />
              </td>
              <td className="py-3 text-right">
                <input 
                  type="number" 
                  step="0.01"
                  value={item.unitPrice}
                  onChange={(e) => updateItem(item.id, 'unitPrice', parseFloat(e.target.value) || 0)}
                  className="w-24 text-right border rounded py-1"
                />
              </td>
              <td className="py-3 text-right font-medium">
                ${(item.quantity * item.unitPrice).toFixed(2)}
              </td>
              <td className="py-3 text-center">
                <button 
                  onClick={() => removeItem(item.id)}
                  className="text-red-500 hover:text-red-700 font-bold"
                  title="Remove Item"
                >
                  &times;
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>

      {/* Add Item Button */}
      <button 
        onClick={addItem}
        className="bg-gray-100 hover:bg-gray-200 text-gray-700 text-xs font-bold py-2 px-4 rounded border border-dashed border-gray-400 mb-8 transition"
      >
        + Add Paper Product Line
      </button>

      {/* Totals Section */}
      <div className="flex justify-end border-t pt-4">
        <div className="w-64 space-y-2 text-sm">
          <div className="flex justify-between text-gray-600">
            <span>Subtotal:</span>
            <span>${subtotal.toFixed(2)}</span>
          </div>
          <div className="flex justify-between text-gray-600">
            <span>PA Sales Tax (6%):</span>
            <span>${taxAmount.toFixed(2)}</span>
          </div>
          <div className="flex justify-between text-lg font-black text-gray-900 border-t pt-2">
            <span>Total Due:</span>
            <span>${total.toFixed(2)}</span>
          </div>
        </div>
      </div>

      {/* Action Footer */}
      <div className="mt-8 pt-6 border-t flex justify-between items-center">
        <p className="text-xs text-gray-400 italic">"You miss 100% of the invoices you don't send." — Wayne Gretzky — Michael Scott</p>
        <button 
          onClick={handlePrint}
          className="bg-red-600 hover:bg-red-700 text-white font-bold py-2 px-6 rounded shadow transition"
        >
          Print / Save PDF
        </button>
      </div>
    </div>
  );
};
```

---

### 📊 Departmental Sign-offs:

- **Kevin Malone (Finance):** *"The math checks out. Subtotal times quantity plus Pennsylvania state tax equals money in our bank account. I approve, as long as we can use some of the proceeds for office snacks."*
- **Dwight Schrute (Security):** *"Make sure SSL encryption is active on the invoice endpoint so corporate spies from Michael Scott Paper Company can't intercept our pricing tiers. Otherwise, acceptable."*
- **Pam Beesly (HR/Ops):** *"It looks clean, Michael. I love the Dunder Mifflin red branding. Let's get it deployed!"*

What's our next feature request for the shop, Michael G.? Inventory tracking? Customer CRM? Let me know and the fleet will spin it up immediately!

