export interface FleetTask<T = any> {
  id: string;
  agent: 'Michael' | 'Dwight' | 'Jim' | 'Pam' | 'Kevin' | 'Ryan' | 'Stanley' | 'Toby' | 'RufloCoder';
  payload: T;
  fallback?: T;
}

