  taskId: string;
  status: 'SUCCESS' | 'FALLBACK_APPLIED' | 'FAILED';
  data: R | null;
  error?: string;
}

export type AgentHandler<T, R> = (payload: T) => Promise<R> | R;

export class MinimalistMicroKernel {
  private handlers = new Map<string, AgentHandler<any, any>>();

  /** Register an agent handler into the micro-kernel */
  public register<T, R>(agent: FleetTask['agent'], handler: AgentHandler<T, R>): this {
    this.handlers.set(agent, handler);
    return this;
  }

