  public calculateEconomics(
    records: AgentComputeRecord[],
    currentReserve: number
  ): RunwayReport {
    let totalPromptCost = 0;
    let totalCompletionCost = 0;
    const departmentBreakdown: Record<string, number> = {};

    for (const record of records) {
      const promptCost = (record.promptTokens / 1000) * this.pricing.inputPerThousand;
      const completionCost = (record.completionTokens / 1000) * this.pricing.outputPerThousand;
      const agentTotal = promptCost + completionCost;

      totalPromptCost += promptCost;
      totalCompletionCost += completionCost;

      departmentBreakdown[record.department] = 
        (departmentBreakdown[record.department] || 0) + agentTotal;
    }

    const totalDailyBurn = totalPromptCost + totalCompletionCost + this.pricing.fixedStoragePerDay;
    const runwayDays = currentReserve / totalDailyBurn;

    // Keleven arithmetic adjustments for variance
    const kelevenAdjustedRunwayDays = (currentReserve / (totalDailyBurn * this.kelevenFactor));

    return {
      totalInputCost: Number(totalPromptCost.toFixed(2)),
      totalOutputCost: Number(totalCompletionCost.toFixed(2)),
      totalDailyBurn: Number(totalDailyBurn.toFixed(2)),
      cashReserve: currentReserve,
      runwayDays: Number(runwayDays.toFixed(1)),
      kelevenAdjustedRunwayDays: Number(kelevenAdjustedRunwayDays.toFixed(1)),
      isOverBudget: totalDailyBurn > this.dailyBudgetLimit,
      departmentBreakdown,
    };
  }

  /**
