        allowed: false,
        reason: `HARD_CIRCUIT_BREAKER_TRIPPED: Projected daily burn $${(currentDailyBurn + estimatedCost).toFixed(2)} exceeds cap of $${this.dailyBudgetLimit}.`,
      };
    }

    return { allowed: true };
  }
}

