/**
 * Dunder Mifflin Autonomous Enterprise Fleet
 * Compute Cost Micro-Kernel (Minimalist Architecture)
 */

export interface ModelPricing {
  inputPer1k: number;
  outputPer1k: number;
}

export interface AgentRunLog {
  agentName: string;
  model: string;
  inputTokens: number;
  outputTokens: number;
  durationSec: number;
  hardwarePerHour?: number; // Optional local node compute cost
}

export interface CostReport {
  agentName: string;
  model: string;
  tokenCost: number;
  computeCost: number;
  totalCost: number;
  efficiencyRatio: string;
}

export class ComputeCostMicroKernel {
  private static readonly PRICING_TABLE: Record<string, ModelPricing> = {
    "gpt-4o": { inputPer1k: 0.0025, outputPer1k: 0.0100 },
    "gpt-4o-mini": { inputPer1k: 0.00015, outputPer1k: 0.0006 },
    "claude-3-5-sonnet": { inputPer1k: 0.0030, outputPer1k: 0.0150 },
    "claude-3-haiku": { inputPer1k: 0.00025, outputPer1k: 0.00125 },
    "local-llama-3-8b": { inputPer1k: 0.00000, outputPer1k: 0.00000 },
  };

  /**
   * Audit a single agent execution batch
   */
  public static calculateRunCost(run: AgentRunLog): CostReport {
    const rates = this.PRICING_TABLE[run.model] || { inputPer1k: 0.001, outputPer1k: 0.002 };

    // Token burn calculation
    const inputCost = (run.inputTokens / 1000) * rates.inputPer1k;
    const outputCost = (run.outputTokens / 1000) * rates.outputPer1k;
    const tokenCost = Number((inputCost + outputCost).toFixed(6));

    // Hardware compute runtime calculation (Default $0.05/hr if self-hosted worker node)
    const hourlyRate = run.hardwarePerHour ?? 0.05;
    const computeCost = Number(((run.durationSec / 3600) * hourlyRate).toFixed(6));

    const totalCost = Number((tokenCost + computeCost).toFixed(4));
    const tokensTotal = run.inputTokens + run.outputTokens;
    const efficiencyRatio = totalCost > 0 
      ? `${Math.round(tokensTotal / totalCost).toLocaleString()} tokens/$`
      : "Free Tier / Local";

    return {
      agentName: run.agentName,
      model: run.model,
      tokenCost,
      computeCost,
      totalCost,
      efficiencyRatio
    };
  }

  /**
   * Aggregate fleet metrics into an executive ledger
   */
  public static auditFleet(runs: AgentRunLog[]): {
    breakdown: CostReport[];
    grandTotal: number;
    kevinVerdict: string;
  } {
    const breakdown = runs.map(run => this.calculateRunCost(run));
    const grandTotal = Number(
      breakdown.reduce((sum, item) => sum + item.totalCost, 0).toFixed(4)
    );

    let kevinVerdict = "👍 Numbers good. No Keleven needed. We can still buy M&Ms.";
    if (grandTotal > 50.00) {
      kevinVerdict = "⚠️ Warning: Compute burn high. Corporate might notice Oscar's spreadsheets.";
    }

    return {
      breakdown,
      grandTotal,
      kevinVerdict
    };
  }
}

