```typescript
import { createHmac, timingSafeEqual, randomBytes } from 'crypto';

// --- TYPES & INTERFACES ---
export type SecurityRole = 'RegionalManager' | 'AssistantRegionalManager' | 'Sales' | 'HR' | 'Accounting' | 'Guest';

export interface SecurityContext {
  userId: string;
  role: SecurityRole;
  scopes: string[];
  issuedAt: number;
  nonce: string;
}

export interface SecurityGateResult {
  granted: boolean;
  reason?: string;
  context?: SecurityContext;
}

// --- MINIMALIST ZERO-TRUST MICRO-KERNEL ---
export class ZeroTrustMicroKernel {
  private readonly secretKey: string;
  private readonly revokedNonces: Set<string> = new Set();
  private readonly tokenTtlMs: number;

  constructor(secretKey: string = process.env.ZERO_TRUST_SECRET || 'dunder-mifflin-quantum-secret-2026', ttlMs: number = 300000) {
    this.secretKey = secretKey;
    this.tokenTtlMs = ttlMs; // 5-minute default ephemeral lifetime
  }

  /**
   * Mint an ephemeral, cryptographically-sealed authorization proof
   */
  public mintProof(userId: string, role: SecurityRole, scopes: string[]): string {
    const context: SecurityContext = {
      userId,
      role,
      scopes,
      issuedAt: Date.now(),
      nonce: randomBytes(16).toString('hex'),
    };

    const payload = Buffer.from(JSON.stringify(context)).toString('base64url');
    const signature = this.sign(payload);
    return `${payload}.${signature}`;
  }

  /**
   * Verify every request on every transaction boundary (Never Trust, Always Verify)
   */
  public evaluateGate(proof: string, requiredScope: string, allowedRoles?: SecurityRole[]): SecurityGateResult {
    if (!proof || !proof.includes('.')) {
      return { granted: false, reason: 'SECURITY_VIOLATION: Missing or malformed authentication proof.' };
    }

    const [payload, signature] = proof.split('.');
    const expectedSignature = this.sign(payload);

    // Timing-safe cryptographic comparison prevents side-channel attacks
    const sigA = Buffer.from(signature, 'utf8');
    const sigB = Buffer.from(expectedSignature, 'utf8');
    if (sigA.length !== sigB.length || !timingSafeEqual(sigA, sigB)) {
      return { granted: false, reason: 'SECURITY_VIOLATION: Cryptographic proof tampering detected.' };
    }

    try {
      const context: SecurityContext = JSON.parse(Buffer.from(payload, 'base64url').toString('utf8'));

      // 1. Time Drift & Expiration Check
      if (Date.now() - context.issuedAt > this.tokenTtlMs) {
        return { granted: false, reason: 'SECURITY_VIOLATION: Ephemeral proof expired.' };
      }

      // 2. Replay Protection
      if (this.revokedNonces.has(context.nonce)) {
        return { granted: false, reason: 'SECURITY_VIOLATION: Nonce replay detected.' };
      }

      // 3. Role-Based Perimeter Assertion
      if (allowedRoles && allowedRoles.length > 0 && !allowedRoles.includes(context.role)) {
        return { granted: false, reason: `SECURITY_VIOLATION: Role '${context.role}' does not satisfy access tier.` };
      }

      // 4. Scope Least-Privilege Assertion
      if (!context.scopes.includes(requiredScope) && !context.scopes.includes('*')) {
        return { granted: false, reason: `SECURITY_VIOLATION: Required scope '${requiredScope}' not held.` };
      }

      return { granted: true, context };
    } catch {
      return { granted: false, reason: 'SECURITY_VIOLATION: Corrupt context payload.' };
    }
  }

  /**
   * Revoke a context token instantly (e.g., during active containment)
   */
  public revoke(proof: string): void {
    try {
      const [payload] = proof.split('.');
      const context: SecurityContext = JSON.parse(Buffer.from(payload, 'base64url').toString('utf8'));
      this.revokedNonces.add(context.nonce);
    } catch {
      // Intentionally silent
    }
  }

  private sign(data: string): string {
    return createHmac('sha256', this.secretKey).update(data).digest('base64url');
  }
}
