  metadata?: Record<string, unknown>;
}

export interface AgentContext {
  agentId: string;
  role: string;
  authorityLevel: number;
  permissions: string[];
}

export class ZeroTrustPerimeterAuditor {
  private static readonly DISALLOWED_IP_RANGES = [
    /^0\./,                // "This" network
    /^10\./,               // Private IPv4 (Class A)
    /^127\./,              // Loopback
    /^169\.254\./,         // Link-local / Cloud Metadata (AWS/GCP/Azure)
    /^172\.(1[6-9]|2[0-9]|3[0-1])\./, // Private IPv4 (Class B)
    /^192\.168\./,         // Private IPv4 (Class C)
    /^::1$/,               // IPv6 Loopback
    /^fe80:/i,             // IPv6 Link-local
    /^fc00:/i              // IPv6 Unique Local Address
  ];

  /**
   * SSRF Guard: Validates destination hostnames and resolves IP addresses
   * to strictly block internal loopback, intranet, and cloud metadata access.
   */
  public static async validateEgressTarget(targetUrl: string): Promise<boolean> {
    try {
      const parsed = new URL(targetUrl);
      if (!['http:', 'https:'].includes(parsed.protocol)) {
        return false;
      }

      const host = parsed.hostname;

      // Direct IP check
      if (net.isIP(host)) {
        return !this.isRestrictedIP(host);
      }

      // DNS Resolution check to prevent DNS rebinding
      const addresses = await dns.resolve(host);
      for (const ip of addresses) {
        if (this.isRestrictedIP(ip)) {
          return false;
        }
      }

      return true;
    } catch {
      return false;
    }
  }

  private static isRestrictedIP(ip: string): boolean {
    return this.DISALLOWED_IP_RANGES.some((regex) => regex.test(ip));
  }

  /**
   * Access Control List (ACL) & Capability Bound Check
   */
  public static auditAgentPermissions(
    agent: AgentContext,
    requiredLevel: number,
    requiredCapability: string
  ): boolean {
    if (agent.authorityLevel < requiredLevel) {
      return false;
    }
    return agent.permissions.includes(requiredCapability);
  }

  /**
   * Executes the full company OS defensive integrity suite.
   */
  public static async runFullAudit(): Promise<AuditReport> {
    const report: AuditReport = {
      timestamp: new Date().toISOString(),
