```typescript
/**
 * @file MicroKernel.ts
 * @description Direct Minimalist Micro-Kernel for Dunder Mifflin Autonomous Fleet.
 * Zero external dependencies. Lean, event-driven task routing.
 */

export interface TaskContext {
  taskId: string;
  payload: Record<string, unknown>;
  timestamp: number;
}

export interface TaskResult<T = unknown> {
  taskId: string;
  status: 'SUCCESS' | 'FAILED';
  data?: T;
  error?: string;
  executionTimeMs: number;
}

export type TaskHandler<TInput = any, TOutput = any> = (
  ctx: TaskContext & { payload: TInput }
) => Promise<TOutput>;

export class MicroKernel {
  private registry = new Map<string, TaskHandler>();

  /**
   * Register a capability / worker plugin
   */
  public register<TIn, TOut>(taskType: string, handler: TaskHandler<TIn, TOut>): void {
    if (this.registry.has(taskType)) {
      throw new Error(`[MicroKernel] Handler for '${taskType}' is already registered.`);
    }
    this.registry.set(taskType, handler);
  }

  /**
   * Dispatch and execute an operational task through the kernel
   */
  public async dispatch<TIn = any, TOut = any>(
    taskType: string,
    payload: TIn
  ): Promise<TaskResult<TOut>> {
    const handler = this.registry.get(taskType);
    const taskId = `task_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`;
    const start = performance.now();

    if (!handler) {
      return {
        taskId,
        status: 'FAILED',
        error: `No registered handler for operational task: '${taskType}'`,
        executionTimeMs: performance.now() - start,
      };
    }

    try {
      const data = await handler({
        taskId,
        payload,
        timestamp: Date.now(),
      });

      return {
        taskId,
        status: 'SUCCESS',
        data,
        executionTimeMs: Math.round((performance.now() - start) * 100) / 100,
      };
    } catch (err: any) {
      return {
        taskId,
        status: 'FAILED',
        error: err?.message || 'Unknown kernel fault',
        executionTimeMs: Math.round((performance.now() - start) * 100) / 100,
      };
    }
  }
}

