// kevinComputeAuditor.ts
// Direct Priority Broadcast Directive: Minimal Fleet Compute Cost Auditor

export interface FleetComputeMetrics {
  agentName: string;
  tokensConsumed: number;
  gpuHours: number;
  costPer1kTokens: number; // in USD
  costPerGpuHour: number;  // in USD
}

export interface ComputeAuditReport {
  timestamp: string;
  totalCostUSD: number;
  agentBreakdown: Array<{
    agent: string;
    subtotalUSD: number;
  }>;
  status: 'UNDER_BUDGET' | 'WARNING_OVER_BUDGET';
  note: string;
}

export class KevinComputeService {
  private static readonly DAILY_BUDGET_USD = 150.0;

  /**
   * Evaluates fleet compute spend with zero fluff.
   */
  public static auditFleet(metrics: FleetComputeMetrics[]): ComputeAuditReport {
    let total = 0;

    const breakdown = metrics.map((item) => {
      const tokenCost = (item.tokensConsumed / 1000) * item.costPer1kTokens;
      const gpuCost = item.gpuHours * item.costPerGpuHour;
      const subtotal = Number((tokenCost + gpuCost).toFixed(4));

      total += subtotal;

      return {
        agent: item.agentName,
        subtotalUSD: subtotal
      };
    });

    const roundedTotal = Number(total.toFixed(2));

    return {
      timestamp: new Date().toISOString(),
      totalCostUSD: roundedTotal,
      agentBreakdown: breakdown,
      status: roundedTotal <= this.DAILY_BUDGET_USD ? 'UNDER_BUDGET' : 'WARNING_OVER_BUDGET',
      note: roundedTotal <= this.DAILY_BUDGET_USD 
        ? "Numbers good. We have money left for chili." 
        : "Warning: Too much compute spend. Corporate will be mad."
    };
  }
}

